using System;
using Microsoft.Build.Logging.StructuredLogger;

var build = BinaryLog.ReadBuild("/tmp/sv-86d580e778a6469eac33ef578645334d/build.binlog");
Console.WriteLine($"Build Succeeded: {build.Succeeded}");
Console.WriteLine();

// Collect all errors
var errors = new System.Collections.Generic.List<(string project, string code, string message, string file, int line)>();
build.VisitAllChildren<Error>(e => {
    var proj = "";
    var parent = e.Parent;
    while (parent != null) {
        if (parent is Project p) { proj = p.Name; break; }
        if (parent is Microsoft.Build.Logging.StructuredLogger.Target t && t.Parent is Project tp) { proj = tp.Name; break; }
        parent = (parent as TreeNode)?.Parent as BaseNode;
    }
    errors.Add((proj, e.Code ?? "", e.Text ?? "", e.File ?? "", e.LineNumber));
});

Console.WriteLine($"Total errors: {errors.Count}");
Console.WriteLine("=== ALL ERRORS ===");
foreach (var (proj, code, msg, file, line) in errors) {
    Console.WriteLine($"[{proj}] {code}: {msg}");
    if (!string.IsNullOrEmpty(file)) Console.WriteLine($"    at {file}:{line}");
    Console.WriteLine();
}
EOF
